examples.template:
Row(
    horizontalArrangement = Arrangement.spacedBy(12.dp),
    verticalAlignment = Alignment.CenterVertically,
) {
    MonarchButton(
        text = {{add}},
        onClick = { count += 1 },
        variant = MonarchButtonVariant.Secondary,
    )
    MonarchText(
        text = if (count == 0) {{empty}} else if (count == 1) "1 item in the list." else "$count items in the list.",
        modifier = Modifier.semantics { liveRegion = LiveRegionMode.Polite },
    )
}

examples.code:
Row(
    horizontalArrangement = Arrangement.spacedBy(12.dp),
    verticalAlignment = Alignment.CenterVertically,
) {
    MonarchButton(
        text = "Add item",
        onClick = { count += 1 },
        variant = MonarchButtonVariant.Secondary,
    )
    MonarchText(
        text = if (count == 0) "No items yet." else if (count == 1) "1 item in the list." else "$count items in the list.",
        modifier = Modifier.semantics { liveRegion = LiveRegionMode.Polite },
    )
}

Box {
    MonarchButton(text = "Archive 3 tickets", onClick = { message = "3 tickets archived" })
    Box(
        modifier = Modifier.semantics {
            liveRegion = LiveRegionMode.Polite
            if (message.isNotEmpty()) contentDescription = message
        },
    )
}
